import numpy as np
one=np.ones_like(t)
def run(k):
    E=1-np.exp(-k*t)
    Pp={'1':one,'P':P,'P2':P**2,'P3':P**3}
    Tb={'1':one,'E':E,'t':t,'Et':E*t,'t2':t**2,'E2':E**2,'tP':None}
    cand={a+'*'+b:Tb[a]*Pp[b] for a in Tb if Tb[a] is not None for b in Pp}
    def nm(keys):
        A=np.column_stack([cand[x] for x in keys])
        c,_,_,_=np.linalg.lstsq(A,dP_dt,rcond=None)
        return np.mean((A@c-dP_dt)**2)/np.var(dP_dt), c
    sel=[]
    for step in range(12):
        best=min(((nm(sel+[kk])[0],kk) for kk in cand if kk not in sel))
        sel.append(best[1])
        if best[0]<1e-9: break
    return best[0],sel,nm(sel)[1]
for k in [0.4,0.5,0.6]:
